initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing an initial Subscription ${subscription} 
        with an id set to ${subscription_id}
        and an initial Entity ${entity}
        with an id set to ${entity_id}
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete Entity Attributes with Response Status Code set to 204     and
        Notification with Response Body containing the key 'json_path_expr=['name']['value']', with the value 'value_to_check=urn:ngsi-ld:null'
}
